sys_script_client.script:
// MSSCUSTODY-3414 - Created this Client Script to show/hide related list depending upon Bulk Task type
function onLoad() {
   //Type appropriate comment here, and begin script below
//    var ga = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
//     ga.addParam('sysparm_name', 'getCountOfTask');
//     ga.addParam('sysparm_bulkid', g_form.getUniqueValue());
//     ga.getXMLAnswer(outcomesParse);

//     function outcomesParse(response) {
// 		var makercount =response;
// 	}

	var blkTskType = g_scratchpad.blkTskRelated;
    if (blkTskType === 'Maker') {
		g_form.showRelatedList('REL:476307b21b6b4210971e6204b24bcbc0'); // Related list for All task
        g_form.showRelatedList('REL:2248aa431b264ed46ed00e1ad34bcbd2'); // Related list for Maker
        g_form.hideRelatedList('REL:404b8ffd1b2b8690ff37eb14b24bcb4d'); // Related list for Pending approval
        g_form.hideRelatedList('REL:83ab47311b6b8690ff37eb14b24bcb50'); // Related list for Pending Rejection

    } else if (blkTskType === 'Checker') {
		g_form.showRelatedList('REL:476307b21b6b4210971e6204b24bcbc0'); // Related list for All task
        g_form.showRelatedList('REL:404b8ffd1b2b8690ff37eb14b24bcb4d'); // Related list for Pending approval
        g_form.hideRelatedList('REL:2248aa431b264ed46ed00e1ad34bcbd2'); // Related list for Maker
        g_form.showRelatedList('REL:83ab47311b6b8690ff37eb14b24bcb50'); // Related list for pending Rejection
    }
	else if (blkTskType === 'GHSS Handler'){
		g_form.hideRelatedList('REL:404b8ffd1b2b8690ff37eb14b24bcb4d'); // Related list for Pending approval
        g_form.hideRelatedList('REL:2248aa431b264ed46ed00e1ad34bcbd2'); // Related list for Maker
        g_form.hideRelatedList('REL:83ab47311b6b8690ff37eb14b24bcb50'); // Related list for pending Rejection
	}
}
